  function lookupFreightCustoms() {
    var input = document.querySelector('[data-freight-customs-no]');
    var result = document.querySelector('[data-freight-customs-result]');
    var button = document.querySelector('[data-freight-customs-lookup]');
    var taxType = document.querySelector('[data-freight-warehouse-tax-type]')?.value || 'tax_exempt';
    if (taxType !== 'taxable') {
      if (result) result.textContent = '目前選的是免稅集運倉，不需要執行關稅比對。';
      return;
    }
    var query = String(input?.value || '').trim();
    if (!query) {
      if (result) result.textContent = '請先輸入關稅號碼或台灣物流單號，再按比對。';
      toast('請先輸入關稅號碼或台灣物流單號');
      return;
    }
    if (button) {
      button.disabled = true;
      button.textContent = '比對中…';
    }
    if (result) result.textContent = '正在從寶輝比對關稅資料...';
    fetch('./freight-customs-lookup.php?q=' + encodeURIComponent(query), { cache: 'no-store' })
      .then(function (res) { return res.json().then(function (payload) { if (!res.ok || !payload.ok) throw new Error(payload.error || '關稅比對失敗'); return payload; }); })
      .then(function (payload) {
        var match = (payload.matches || [])[0];
        if (!match) {
          if (result) result.textContent = '寶輝找不到相符關稅號或台灣物流單號，請手動核對。';
          return;
        }
        if (input) input.value = match.customsNo || query;
        var date = document.querySelector('[data-freight-batch-date]');
        var amount = document.querySelector('[data-freight-batch-amount]');
        if (date && match.date) date.value = String(match.date).slice(0, 10);
        if (amount) amount.value = Number(match.chargeTotalTwd || 0);
        if (result) result.textContent = '已帶入關稅 ' + (match.customsNo || '-') + '，' + match.packageCount + ' 筆台灣物流，收款合計 NT$' + Number(match.chargeTotalTwd || 0).toLocaleString() + '。請填本批實收件數後儲存分攤。';
        toast('已帶入寶輝關稅收款合計');
      })
      .catch(function (error) {
        if (result) result.textContent = error.message || '關稅比對失敗';
        toast(error.message || '關稅比對失敗');
      })
      .finally(function () {
        if (button) {
          button.disabled = false;
          button.textContent = '從寶輝比對關稅';
        }
      });
  }

  function saveFreightItem() {
    var item = freightItemFormData();
    if (!item.productName && !item.sampleBarcode && !item.trackingNo) {
      toast('請先填產品名稱、條碼或物流單號');
      return;
    }
    if (!item.id) item.id = 'FRTI-' + Date.now();
    state.freightTracking = normalizeFreightTracking(state.freightTracking);
    var index = state.freightTracking.items.findIndex(function (row) { return row.id === item.id; });
    if (index >= 0) state.freightTracking.items[index] = Object.assign({}, state.freightTracking.items[index], item);
    else state.freightTracking.items.unshift(item);
    saveFreightTracking().then(function () {
      fillFreightItemForm({});
      toast('產品物流已儲存');
    }).catch(function (error) {
      toast(error.message || '產品物流儲存失敗');
    });
  }

  function saveFreightBatch() {
    var batch = freightBatchFormData();
    if (!batch.customsNo && !batch.note) {
      toast('請先填關稅/集運單號或備註');
      return;
    }
    if (!batch.id) batch.id = 'FRT-' + Date.now();
    state.freightTracking = normalizeFreightTracking(state.freightTracking);
    var index = state.freightTracking.batches.findIndex(function (row) { return row.id === batch.id; });
    if (index >= 0) state.freightTracking.batches[index] = Object.assign({}, state.freightTracking.batches[index], batch);
    else state.freightTracking.batches.unshift(batch);
    saveFreightTracking().then(function () {
      fillFreightBatchForm({});
      toast('集運批次已儲存');
    }).catch(function (error) {
      toast(error.message || '集運批次儲存失敗');
    });
  }

  function renderFreightTracking() {
    var panel = document.querySelector('[data-freight-tracking-panel]');
    if (!panel) return;
    state.freightTracking = normalizeFreightTracking(state.freightTracking);
    fillFreightBatchSelect();
    applyFreightSourceMode();
    var itemDateInput = document.querySelector('[data-freight-item-date]');
    if (itemDateInput && !itemDateInput.value) itemDateInput.value = freightToday();
    var keyword = String(document.querySelector('[data-freight-search]')?.value || '').trim().toLowerCase();
    var batches = state.freightTracking.batches.filter(function (batch) {
      if (!keyword) return true;
      return [batch.date, batch.forwarder, batch.customsNo, batch.consolidationNo, batch.chargeType, batch.status, batch.note].join(' ').toLowerCase().indexOf(keyword) !== -1;
    });
    var items = state.freightTracking.items.filter(function (item) {
      if (!keyword) return true;
      return [item.date, item.platform, item.productCode, item.productName, item.sampleBarcode, item.taiwanBarcode, item.trackingNo, item.progress, item.issueType, item.issueProgress, item.note, freightBatchLabel(freightBatchById(item.batchId))].join(' ').toLowerCase().indexOf(keyword) !== -1;
    }).sort(function (a, b) {
      var aTime = Date.parse(a.createdAt || a.date || '') || 0;
      var bTime = Date.parse(b.createdAt || b.date || '') || 0;
      return bTime - aTime;
    });
    var summary = document.querySelector('[data-freight-summary]');
    if (summary) summary.textContent = '產品物流 ' + items.length + ' 筆 / 集運批次 ' + batches.length + ' 筆';
    var batchList = document.querySelector('[data-freight-batch-list]');
    if (batchList) {
      batchList.innerHTML = batches.map(function (batch) {
        var typeLabel = batch.chargeType === 'shipping' ? '集運運費' : (batch.chargeType === 'none' ? '免稅/免運' : '關稅/手續費');
        return [
          '<article class="freight-card">',
          '<div><b>' + escapeHtml(freightBatchLabel(batch)) + '</b><span>' + escapeHtml(typeLabel + ' / ' + (batch.currency || 'TWD') + ' ' + Number(batch.amount || 0)) + '</span></div>',
          '<p>' + (batch.costMode === 'haohong_weight' ? '豪鴻公斤計價：RMB 8 / 公斤 × 5 = NT$40 / 公斤（請在產品列填實際公斤數）' : '關貿稅金：NT$' + Number(batch.amount || 0) + ' ÷ ' + Number(batch.itemCount || 0) + ' 件 = 每件 NT$' + Number(batch.allocationPerItem || 0)) + ' / 狀態 ' + escapeHtml(batch.status || '-') + '</p>',
          batch.note ? '<small>' + escapeHtml(batch.note) + '</small>' : '<small>無備註</small>',
          '<div class="freight-actions"><button type="button" class="ghost-button" data-freight-batch-edit="' + escapeHtml(batch.id) + '">編輯批次</button><button type="button" class="danger-button" data-freight-batch-delete="' + escapeHtml(batch.id) + '">刪除</button></div>',
          '</article>'
        ].join('');
      }).join('') || '<div class="empty-state">尚未建立集運/關稅批次。</div>';
    }
    var itemList = document.querySelector('[data-freight-item-list]');
    if (itemList) {
      itemList.innerHTML = items.map(function (item) {
        var cost = freightFinalCost(item);
        var batch = freightBatchById(item.batchId);
        var isIssue = item.issueType && item.issueType !== '正常';
        var isPriority = item.platform === '拚張' || item.platform === '拚A';
        var sourceLabel = item.logisticsSource === 'haohong' ? '豪鴻物流' : '拼多多／' + (item.platform || '未填帳號');
        return [
          '<article class="freight-card freight-item-card' + (isIssue ? ' is-freight-issue' : '') + (isPriority ? ' is-customer-priority' : '') + '">',
          '<div class="freight-logistics-compare">',
          '<time><span>物流建檔日期</span><b>' + escapeHtml(item.date || '-') + '</b></time>',
          '<div class="freight-logistics-record-cell"><span>物流紀錄</span><b>' + escapeHtml(item.trackingNo || '-') + '</b><small>' + escapeHtml(item.productName || item.sampleBarcode || '未命名產品') + ' / ' + escapeHtml(item.progress || '待下單') + '</small></div>',
          '<div class="freight-logistics-platform-cell"><span>物流來源</span><b>' + escapeHtml(sourceLabel) + '</b>' + (isPriority ? '<strong>客戶訂單重點追蹤</strong>' : '') + '</div>',
          '</div>',
          '<p>顏色：' + escapeHtml(item.color || '-') + '／尺寸：' + escapeHtml(item.size || '-') + '／數量：' + Number(item.quantity || 1) + '</p><p>中國條碼：' + escapeHtml(item.sampleBarcode || '-') + ' / 台灣條碼：' + escapeHtml(item.taiwanBarcode || '-') + '</p>',
          '<p>集運批次：' + escapeHtml(freightBatchLabel(batch)) + '</p>',
          '<p>成本：' + (cost.isFixedTwd ? '既有台幣成本鎖定 NT$' + cost.base : '人民幣 ' + Number(item.costRmb || 0) + ' × 5 = NT$' + cost.base) + (item.logisticsSource === 'haohong' ? '；豪鴻重量 ' + Number(item.weightKg || 0) + 'kg／運費 NT$' + cost.haohongShipping : '；拼多多批次分攤 NT$' + cost.allocation) + '；本筆成本 NT$' + cost.companyInternalCost + '</p>',
          item.issueType ? '<small>商損/退款：' + escapeHtml(item.issueType) + ' ' + escapeHtml(item.issueProgress || '') + '</small>' : '<small>商損/退款：正常或未填</small>',
          item.note ? '<small>' + escapeHtml(item.note) + '</small>' : '',
          '<div class="freight-actions"><button type="button" class="primary-button" data-freight-product-draft="' + escapeHtml(item.id) + '">帶入產品建檔</button><button type="button" class="ghost-button" data-freight-item-edit="' + escapeHtml(item.id) + '">編輯物流</button><button type="button" class="danger-button" data-freight-item-delete="' + escapeHtml(item.id) + '">刪除</button></div>',
          '</article>'
        ].join('');
      }).join('') || '<div class="empty-state">尚未建立產品物流追蹤。</div>';
    }
    renderFreightExtras();
  }

  function freightItemById(id) {
    return normalizeFreightTracking(state.freightTracking).items.find(function (item) {
      return String(item.id || '') === String(id || '');
    }) || null;
  }

  function productFiledProductForFreightItem(item) {
    item = item || {};
    var explicit = {
      id: String(item.productFiledProductId || '').trim(),
      code: String(item.productFiledProductCode || '').trim(),
      title: String(item.productFiledProductTitle || '').trim()
    };
    if (String(item.productFiledStatus || '').toLowerCase() === 'filed' || explicit.id || explicit.code || explicit.title) return explicit;
    var itemId = String(item.id || item.sourceItemId || '').trim();
    if (!itemId) return null;
    var collections = ['purchaseLogistics', 'logisticsRecords', 'supplierProcurementRecords'];
    var products = Array.isArray(state.products) ? state.products : [];
    for (var productIndex = 0; productIndex < products.length; productIndex += 1) {
      var candidate = products[productIndex] || {};
      var linkedIds = [candidate.freightItemId, candidate.costFreightItemId];
      collections.forEach(function (collection) {
        (Array.isArray(candidate[collection]) ? candidate[collection] : []).forEach(function (row) {
          row = row || {};
          linkedIds.push(row.freightItemId, row.costFreightItemId, row.sourceItemId);
        });
      });
      if (linkedIds.some(function (value) { return String(value || '').trim() === itemId; })) {
        return {
          id: String(candidate.id || '').trim(),
          code: String(candidate.code || candidate.barcode || '').trim(),
          title: String(candidate.title || candidate.name || '').trim()
        };
      }
    }
    return null;
  }

  function productFiledInfoMatchesProduct(filed, product) {
    filed = filed || {};
    product = product || {};
    var filedId = normalizeProductCostTracking(filed.id || '');
    var productId = normalizeProductCostTracking(product.id || '');
    if (filedId && productId && filedId === productId) return true;
    var filedCode = normalizeProductCostTracking(filed.code || '');
    var productCode = normalizeProductCostTracking(product.code || product.barcode || '');
    return !!(filedCode && productCode && filedCode === productCode);
  }

  function productFiledByCurrentEditedProduct(item) {
    if (!productEditId) return false;
    var filed = productFiledProductForFreightItem(item);
    if (!filed) return false;
    var current = (Array.isArray(state.products) ? state.products : []).find(function (product) {
      return String(product && product.id || '') === String(productEditId || '');
    }) || { id: productEditId, code: document.querySelector('[data-new-product-code]')?.value || '' };
    return productFiledInfoMatchesProduct(filed, current);
  }

  function productCostFreightItemBlockedForEdit(item) {
    var filed = productFiledProductForFreightItem(item);
    var batch = freightBatchById(item && (item.batchId || item.freightBatchId || item.costBatchId || '')) || {};
    // A product metadata link is not a completed inbound.  Keep a not-yet-
    // received or failed-direct-inbound freight item available so staff can
    // finish it later.  Only the backend's durable inventory evidence closes
    // the row and prevents another product from claiming it.
    var inventoryPosted = productCostFreightInventoryPosted(item || {}, batch);
    return !!filed && inventoryPosted && !productFiledByCurrentEditedProduct(item);
  }

