  function saveFreightDamage() {
    var item = freightDamageFormData();
    if (!item.productName && !item.productCode && !item.trackingNo) { toast('請填產品、條碼或物流單號'); return; }
    if (!item.id) item.id = 'FDG-' + Date.now();
    state.freightTracking = normalizeFreightTracking(state.freightTracking);
    var index = state.freightTracking.damages.findIndex(function (row) { return row.id === item.id; });
    if (index >= 0) state.freightTracking.damages[index] = Object.assign({}, state.freightTracking.damages[index], item);
    else state.freightTracking.damages.unshift(item);
    saveFreightTracking().then(function () { fillFreightDamageForm({}); toast('商品故障/損壞處理已儲存'); }).catch(function (error) { toast(error.message || '儲存失敗'); });
  }

  function renderFreightExtras() {
    var keyword = String(document.querySelector('[data-freight-search]')?.value || '').trim().toLowerCase();
    var checkpointList = document.querySelector('[data-freight-checkpoint-list]');
    var damageList = document.querySelector('[data-freight-damage-list]');
    var checkpoints = (state.freightTracking.checkpoints || []).filter(function (item) {
      return !keyword || [item.date, item.platform, item.productName, item.note].join(' ').toLowerCase().indexOf(keyword) !== -1;
    });
    var damages = (state.freightTracking.damages || []).filter(function (item) {
      return !keyword || [item.date, item.platform, item.productCode, item.productName, item.trackingNo, item.issueType, item.progress, item.note].join(' ').toLowerCase().indexOf(keyword) !== -1;
    });
    if (checkpointList) checkpointList.innerHTML = checkpoints.map(function (item) {
      return '<article class="freight-mini-card"><b>' + escapeHtml(item.platform || '-') + '</b><span>' + escapeHtml(item.productName || '-') + '</span><small>' + escapeHtml(item.date || '') + (item.note ? ' / ' + escapeHtml(item.note) : '') + '</small><button type="button" class="ghost-button" data-freight-checkpoint-edit="' + escapeHtml(item.id) + '">編輯</button></article>';
    }).join('') || '<div class="empty-state">尚未記錄平台追蹤位置。</div>';
    if (damageList) damageList.innerHTML = damages.map(function (item) {
      return '<article class="freight-mini-card is-damage"><b>' + escapeHtml(item.issueType || '異常') + ' / ' + escapeHtml(item.progress || '待處理') + '</b><span>' + escapeHtml(item.productName || item.productCode || item.trackingNo || '-') + '</span><small>' + escapeHtml([item.platform, item.trackingNo, item.note].filter(Boolean).join(' / ')) + '</small><button type="button" class="ghost-button" data-freight-damage-edit="' + escapeHtml(item.id) + '">編輯</button></article>';
    }).join('') || '<div class="empty-state">尚無商品故障或損壞紀錄。</div>';
  }

  function freightSheetPreviewRows(rows) {
    var box = document.querySelector('[data-freight-import-preview]');
    var summary = document.querySelector('[data-freight-import-summary]');
    if (summary) summary.textContent = '表格預覽：平台追蹤 ' + Number(rows.checkpoints || 0) + ' 筆 / 商損 ' + Number(rows.damages || 0) + ' 筆 / 待建立預購物流 ' + Number(rows.items || 0) + ' 筆。';
    if (!box) return;
    box.innerHTML = (rows.preview || []).slice(0, 18).map(function (item) {
      return '<article><b>' + escapeHtml(item.platform || '未辨識平台') + '</b><span>' + escapeHtml(item.productName || '-') + '</span><small>' + escapeHtml([item.variantText, item.colorName, item.sizeName, item.trackingNo, 'RMB ' + Number(item.costRmb || 0)].filter(Boolean).join(' / ')) + '</small></article>';
    }).join('') || '<div class="empty-state">沒有可建立的集運資料。</div>';
  }

  function loadFreightSheetPreview() {
    var button = document.querySelector('[data-freight-sheet-preview]');
    if (button) button.disabled = true;
    fetch('./freight-sheet-import.php?action=preview&_=' + Date.now(), { cache: 'no-store' })
      .then(function (res) { return res.json().then(function (payload) { if (!res.ok || !payload.ok) throw new Error(payload.error || '表格讀取失敗'); return payload; }); })
      .then(function (payload) {
        freightSheetPreview = Array.isArray(payload.items) ? payload.items : [];
        freightSheetPreviewRows({ checkpoints: (payload.checkpoints || []).length, damages: (payload.damages || []).length, items: freightSheetPreview.length, preview: freightSheetPreview });
        var apply = document.querySelector('[data-freight-sheet-apply]');
        if (apply) apply.disabled = !freightSheetPreview.length;
        state.freightTracking.importMeta = { source: payload.source || '掏寶追蹤物流', loadedAt: new Date().toISOString(), checkpoints: payload.checkpoints || [], damages: payload.damages || [] };
        state.freightTracking._importCheckpoints = payload.checkpoints || [];
        state.freightTracking._importDamages = payload.damages || [];
      })
      .catch(function (error) { toast(error.message || '表格讀取失敗'); })
      .finally(function () { if (button) button.disabled = false; });
  }

  function applyFreightSheetPreview() {
    if (!freightSheetPreview.length) { toast('請先載入表格預覽'); return; }
    state.freightTracking = normalizeFreightTracking(state.freightTracking);
    var exists = new Set(state.freightTracking.items.map(function (item) { return [item.trackingNo, item.productName, item.variantText].join('|'); }));
    var added = 0;
    freightSheetPreview.forEach(function (item) {
      var key = [item.trackingNo, item.productName, item.variantText].join('|');
      if (exists.has(key)) return;
      state.freightTracking.items.push(Object.assign({ id: 'FRTI-' + Date.now() + '-' + added, progress: '東莞', quantity: 1, preorderOnly: true, importSource: 'taobao-tracking-sheet' }, item));
      exists.add(key); added += 1;
    });
    (state.freightTracking._importCheckpoints || []).forEach(function (item) {
      if (!(state.freightTracking.checkpoints || []).some(function (row) { return row.platform === item.platform && row.productName === item.productName; })) state.freightTracking.checkpoints.push(Object.assign({ id: 'FCP-' + Date.now() + '-' + Math.random().toString(36).slice(2, 6) }, item));
    });
    (state.freightTracking._importDamages || []).forEach(function (item) {
      if (!(state.freightTracking.damages || []).some(function (row) { return row.trackingNo === item.trackingNo && row.productName === item.productName; })) state.freightTracking.damages.push(Object.assign({ id: 'FDG-' + Date.now() + '-' + Math.random().toString(36).slice(2, 6) }, item));
    });
    saveFreightTracking().then(function () { toast('已建立 ' + added + ' 筆預購物流；未建立現貨庫存或前台上架'); }).catch(function (error) { toast(error.message || '匯入儲存失敗'); });
  }

  function freightVariantQuantity(item) {
    item = item || {};
    var quantity = Number(item.quantity !== undefined ? item.quantity : item.qty);
    return Number.isFinite(quantity) && quantity > 0 ? quantity : 1;
  }

  function normalizeFreightDraftImages(value) {
    var seen = new Set();
    return (Array.isArray(value) ? value : []).map(function (src) { return String(src || '').trim(); }).filter(function (src) {
      if (!src || seen.has(src) || !/^(?:data:image\/|https?:\/\/|\.\.\/|\.\/|\/)/i.test(src)) return false;
      seen.add(src);
      return true;
    }).slice(0, 8);
  }

  function normalizeFreightDraftColorImages(value) {
    var result = {};
    if (!value || typeof value !== 'object') return result;
    Object.keys(value).slice(0, 30).forEach(function (color) {
      var name = String(color || '').trim();
      var image = String(value[color] || '').trim();
      if (name && /^(?:data:image\/|https?:\/\/|\.\.\/|\.\/|\/)/i.test(image)) result[name] = image;
    });
    return result;
  }

  function freightVariantRows(item) {
    item = item || {};
    if (Array.isArray(item.variants) && item.variants.length) {
      var colorImages = normalizeFreightDraftColorImages(item.colorImages || {});
      return item.variants.map(function (line) {
        line = line && typeof line === 'object' ? line : {};
        return Object.assign({}, item, line, {
          category: String(line.category || item.category || '').trim(),
          color: String(line.color || line.colorName || '').trim(),
          size: String(line.size || line.sizeName || 'NO SIZE').trim() || 'NO SIZE',
          quantity: freightVariantQuantity(line),
          sampleBarcode: String(line.sampleBarcode || line.taiwanBarcode || item.sampleBarcode || '').trim(),
          taiwanBarcode: String(line.taiwanBarcode || line.sampleBarcode || item.taiwanBarcode || '').trim(),
          image: String(line.image || line.colorImage || colorImages[String(line.color || line.colorName || '').trim()] || '').trim()
        });
      });
    }
    return [item];
  }

  function applyFreightVariantToProductDraft(item) {
    item = item || {};
    var color = String(item.color || item.colorName || '待補顏色').trim() || '待補顏色';
    var size = String(item.size || item.sizeName || 'NO SIZE').trim() || 'NO SIZE';
    var quantity = freightVariantQuantity(item);
    var ident = productColorIdentity({ name: color, code: item.colorCode || '' });
    color = ident.name || color;
    var hasOnlyUntouchedDefaultColor = productDraft.colors.length === 1 &&
      productColorIdentity(productDraft.colors[0]).name === canonicalChineseColorName('黑色') && !productDraft.colors[0].image &&
      Object.keys(productDraft.stocks || {}).length === 0;
    if (hasOnlyUntouchedDefaultColor && ident.name !== canonicalChineseColorName('黑色')) productDraft.colors = [];
    var colorImage = item.image || item.colorImage || '';
    var existingColor = productDraft.colors.find(function (row) { return productColorIdentity(row).name === ident.name; });
    if (!existingColor) productDraft.colors.push({ code: ident.code || item.colorCode || '', name: color, image: colorImage });
    else if (colorImage && !existingColor.image) existingColor.image = colorImage;
    if (productDraft.sizes.indexOf(size) === -1) productDraft.sizes.push(size);
    // Freight quantities are only a receiving reference. Inventory is added by
    // the later receipt transaction using the confirmed actual quantity.
    productDraft.stocks[color + '||' + size] = 0;
    return { color: color, size: size, quantity: quantity, colorNeedsReview: color === '待補顏色' };
  }

  function freightItemProductDraft(item) {
    item = item || {};
    var batch = freightBatchById(item.batchId) || {};
    var cost = freightFinalCost(item);
    var authoritativeBarcode = item.catalogProductCode || item.sampleBarcode || item.taiwanBarcode || item.productCode || '';
    var authoritativeBaseCode = labelBarcodeBaseProductCode(authoritativeBarcode) || '';
    var itemTrackingNo = item.trackingNo || item.logisticsTrackingNo || item.supplierTrackingNo || item.taiwanTrackingNo || (item.trackingNos || [])[0] || (item.trackingNumbers || [])[0] || '';
    var disposition = productCostInventoryDisposition(item, itemTrackingNo, batch);
    var isDirectChinaSample = disposition.actualReceived && disposition.destination.code === 'CN_DONGGUAN';
    return {
      source: 'freight-tracking',
      createdAt: new Date().toISOString(),
      // China-received Dongguan items are internal China samples; other freight imports remain procurement candidates.
      productMode: disposition.mode,
      preorderOnly: disposition.mode === 'preorder',
      chinaSample: isDirectChinaSample,
      // Freight intake generates the official company barcode.  Legacy
      // productId/skuId values may point at a different old catalog record, so
      // the base before P is the source of truth when carrying into products.
      productCode: authoritativeBaseCode || item.taiwanBarcode || item.sampleBarcode || '',
      productName: item.productName || '',
      brand: item.brand || item.brandName || '',
      spec: item.spec || item.specification || item.variantSpec || '',
      category: item.category || (Array.isArray(item.variants) && item.variants[0] && item.variants[0].category) || '',
      costTwd: cost.companyInternalCost || cost.displayCost || cost.base || 0,
      costRmb: Number(item.costRmb || 0),
      color: item.color || '',
      size: item.size || 'NO SIZE',
      quantity: freightVariantRows(item).reduce(function (sum, line) { return sum + freightVariantQuantity(line); }, 0),
      variants: freightVariantRows(item),
      productImages: normalizeFreightDraftImages(item.productImages || item.images || []),
      colorImages: normalizeFreightDraftColorImages(item.colorImages || {}),
      weightKg: Number(item.weightKg || 0),
      logisticsSource: item.logisticsSource || '',
      weightKg: Number(item.weightKg || 0),
      platform: item.platform || '',
      trackingNo: itemTrackingNo,
      freightBatchId: item.batchId || batch.id || '',
      costBatchId: item.batchId || batch.id || '',
      freightItemId: item.sourceItemId || item.id || '',
      destinationWarehouse: disposition.destination.code || cost.destination && cost.destination.code || item.destinationWarehouse || batch.destinationWarehouse || '',
      destinationSite: disposition.destination.site || cost.destination && cost.destination.site || '',
      handlingPerItemTwd: cost.warehouseHandling || 0,
      customsNo: cost.destination && cost.destination.code === 'CN_DONGGUAN' ? '' : (batch && (batch.customsNo || batch.consolidationNo) || ''),
      customsAllocationTwd: cost.allocation || 0,
      freightTwd: cost.haohongShipping || 0,
      finalCostTwd: cost.companyInternalCost || cost.base || 0,
      progress: item.progress || batch.status || '',
      freightReceivingStatus: item.progress || batch.status || '',
      inventoryOwnership: productCostInventoryOwnership(item),
      customerAllocationRequired: false,
      date: item.date || freightToday(),
      sampleBarcode: item.sampleBarcode || '',
      taiwanBarcode: item.taiwanBarcode || '',
      note: item.note || ''
    };
  }

  function applyFreightProductDraft(draft) {
    if (!draft || !document.querySelector('[data-new-product-code]')) return false;
    if (draft.category && (state.categories || []).indexOf(draft.category) === -1) {
      state.categories = (state.categories || []).concat([draft.category]);
    }
    var map = {
      '[data-new-product-code]': labelBarcodeBaseProductCode(draft.productCode || draft.taiwanBarcode || draft.sampleBarcode || ''),
      '[data-new-product-title]': draft.productName || '',
      '[data-new-product-brand]': draft.brand || draft.brandName || '',
      '[data-new-product-spec]': draft.spec || draft.specification || draft.variantSpec || '',
      '[data-new-product-category]': draft.category || '',
      '[data-new-product-cost]': draft.costTwd || '',
      '[data-new-product-cost-rmb]': draft.costRmb || '',
      '[data-new-product-weight-kg]': draft.weightKg || '',
      '[data-new-product-weight-kg]': draft.weightKg || '',
      '[data-new-product-customs-no]': draft.customsNo || '',
      '[data-new-product-customs-allocation]': draft.customsAllocationTwd || 0,
      '[data-new-product-freight-twd]': draft.freightTwd || 0,
      '[data-new-product-final-cost]': draft.finalCostTwd || draft.costTwd || 0,
      '[data-product-freight-source]': draft.logisticsSource || 'pinduoduo',
      '[data-product-cost-mode]': (draft.logisticsSource === 'haohong' ? 'haohong_freight' : 'pinduoduo_freight'),
      '[data-product-visibility-mode]': draft.productMode || 'preorder',
      '[data-product-logistics-platform]': draft.platform || '其他',
      '[data-product-logistics-no]': draft.trackingNo || '',
      '[data-product-logistics-progress]': draft.progress || '',
      '[data-product-logistics-date]': draft.date || freightToday(),
      '[data-product-logistics-note]': draft.note || ('物流集運帶入：樣品條碼 ' + (draft.sampleBarcode || '-') + ' / 台灣條碼 ' + (draft.taiwanBarcode || '-'))
    };
    Object.keys(map).forEach(function (selector) {
      var el = document.querySelector(selector);
      if (el && map[selector] !== undefined && map[selector] !== null) el.value = map[selector];
    });
    var freightCodeInput = document.querySelector('[data-new-product-code]');
    if (freightCodeInput && draft.productCode) {
      freightCodeInput.dataset.autoCategoryCode = '0';
      freightCodeInput.dataset.codeSource = 'freight';
    }
    var draftDestination = productCostDestinationRule(draft.destinationWarehouse || draft.destinationSite || '');
    applyProductInventoryWarehouseFromDestination(draftDestination, draft.productMode !== 'preorder');
    var costBatchSelect = document.querySelector('[data-product-cost-batch-select]');
    var draftBatchId = String(draft.freightBatchId || draft.costBatchId || '').trim();
    if (costBatchSelect && draftBatchId) costBatchSelect.dataset.pendingValue = draftBatchId;
    var trackingSearch = document.querySelector('[data-product-cost-tracking-search]');
    var trackingInput = document.querySelector('[data-product-cost-tracking-no]');
    var freightItemInput = document.querySelector('[data-product-cost-freight-item-id]');
    var receivingStatusInput = document.querySelector('[data-product-cost-receiving-status]');
    if (trackingSearch) trackingSearch.value = draft.trackingNo || '';
    if (trackingInput) trackingInput.value = draft.trackingNo || '';
    if (freightItemInput) freightItemInput.value = draft.freightItemId || '';
    if (receivingStatusInput) receivingStatusInput.value = draft.freightReceivingStatus || draft.progress || 'pending';
    state._productCostPreferredTracking = draft.trackingNo || '';
    applyProductCostMode();
    syncProductPhysicalLocationFields();
    var freightDraftImages = normalizeFreightDraftImages(draft.productImages || draft.images || []);
    productDraft.images = normalizeFreightDraftImages((productDraft.images || []).concat(freightDraftImages));
    if (productDraft.images.length && productDraft.mainImageIndex >= productDraft.images.length) productDraft.mainImageIndex = 0;
    var freightDraftColorImages = normalizeFreightDraftColorImages(draft.colorImages || {});
    (draft.variants || []).forEach(function (line) {
      var color = String(line && (line.color || line.colorName) || '').trim();
      if (color && freightDraftColorImages[color] && !line.image && !line.colorImage) line.image = freightDraftColorImages[color];
    });
    var freightVariantRowsToApply = freightVariantRows(draft);
    var freightVariantResults = freightVariantRowsToApply.map(applyFreightVariantToProductDraft);
    var freightVariant = {
      quantity: freightVariantResults.reduce(function (sum, row) { return sum + Number(row.quantity || 0); }, 0),
      colorNeedsReview: freightVariantResults.some(function (row) { return row.colorNeedsReview; })
    };
    upsertProductProcurementSourceRecord(Object.assign({}, draft, {
      supplier: draft.platform || '',
      recordType: 'supplier-procurement',
      progress: draft.progress || '產品建檔',
      note: draft.note || ('物流集運帶入：樣品條碼 ' + (draft.sampleBarcode || '-') + ' / 台灣條碼 ' + (draft.taiwanBarcode || '-'))
    }));
    renderProductCreate();
    var categoryInput = document.querySelector('[data-new-product-category]');
    if (categoryInput && draft.category) categoryInput.value = draft.category;
    var batch = draftBatchId ? freightBatchById(draftBatchId) : null;
    if (costBatchSelect && draftBatchId && Array.from(costBatchSelect.options).some(function (option) { return option.value === draftBatchId; })) {
      costBatchSelect.value = draftBatchId;
      applyProductCostBatchSelection();
    } else {
      applyProductCostDestination(draft, batch);
      applyProductFreightSourceMode();
      fillProductCostChargeSelect(batch);
      applyProductCostChargeSelection();
      if (!draftBatchId) {
        var verifiedDraftItem = verifiedProductCostFreightItem(draft.freightItemId, draft.trackingNo);
        var draftDisposition = productCostInventoryDisposition(verifiedDraftItem, draft.trackingNo, null);
        setProductCostTrackingMessage(draftDisposition.actualReceived
          ? '已對到「' + draftDisposition.destination.site + '／' + draftDisposition.progress + '」物流物件；產品儲存後會由後端防重複增加' + draftDisposition.destination.warehouse + '庫存。'
          : '這筆物流尚未標記收到／到貨；可先存產品資料，庫存維持 0，不需先建進貨草稿或關稅資料。', draftDisposition.actualReceived ? 'success' : 'warning');
        var directStatus = document.querySelector('[data-product-cost-status]');
        if (draftDisposition.actualReceived && directStatus) directStatus.textContent = draftDisposition.destination.site + '／' + draftDisposition.progress + '｜可直接建檔入庫';
      }
    }
    renderProductLogisticsEditor();
    var platformInput = document.querySelector('[data-product-logistics-platform]');
    if (platformInput && draft.platform && Array.from(platformInput.options).some(function (option) { return option.value === draft.platform; })) platformInput.value = draft.platform;
    document.querySelector('[data-new-product-code]')?.focus();
    toast('已帶入產品建檔 ' + freightVariantRowsToApply.length + ' 組／數量 ' + freightVariant.quantity + ' 件' + (freightDraftImages.length || Object.keys(freightDraftColorImages).length ? '／圖片已一起帶入' : '') + (freightVariant.colorNeedsReview ? '；請先補正顏色' : '') + '，請核對後再儲存商品');
    return true;
  }

  function applyPendingFreightProductDraft(options) {
    options = options && options.directOnly === true ? options : {};
    if (!document.querySelector('[data-new-product-code]')) return;
    try {
      var draftKey = 'lingzanzan-v1-product-create-draft';
      var regularDraft = sessionStorage.getItem(draftKey);
      var freightDraft = sessionStorage.getItem('lingzanzan-v1-freight-product-draft');
      var raw = regularDraft || freightDraft;
      if (!raw) return;
      var parsedDraft = JSON.parse(raw);
      if (!regularDraft && freightDraft && state._freightTrackingLoaded !== true) {
        // Show the freight product immediately instead of leaving an empty
        // form for several seconds while the large freight file loads. Keep
        // the draft so it is applied again after the server data is verified.
        if (!options.directOnly) applyFreightProductDraft(parsedDraft);
        return false;
      }
      if (options.directOnly && !regularDraft && String(parsedDraft.freightBatchId || parsedDraft.costBatchId || '').trim()) return false;
      if (!applyFreightProductDraft(parsedDraft)) return false;
      sessionStorage.removeItem(draftKey);
      sessionStorage.removeItem('lingzanzan-v1-freight-product-draft');
      return true;
    } catch (error) {
      console.warn('freight product draft apply failed', error);
      toast('物流產品資料尚未完整帶入，請返回物流頁重新按「帶入產品建檔」');
      return false;
    }
  }

  function sendFreightItemToProductDraft(itemId) {
    var item = freightItemById(itemId);
    if (!item) {
      toast('找不到這筆物流資料');
      return;
    }
    var draft = freightItemProductDraft(item);
    if (applyFreightProductDraft(draft)) return;
    sessionStorage.setItem('lingzanzan-v1-freight-product-draft', JSON.stringify(draft));
    location.href = './admin-products.html?fromFreight=1&v=20260709-freight-product-draft-1#product-create';
  }

  function sendPreorderItemToProductDraft(value) {
    var parts = String(value || '').split('|');
    var inquiryId = parts[0] || '';
    var itemIndex = Number(parts[1]);
    var inquiry = (state.inquiries || []).find(function (row) { return String(row.id || '') === inquiryId; });
    var item = inquiry && Array.isArray(inquiry.items) ? inquiry.items[itemIndex] : null;
    if (!inquiry || !item) {
      toast('找不到這筆預購商品，請重新整理後再試');
      return;
    }
    var platform = String(inquiry.purchasePlatform || inquiry.platform || '').trim();
    var draft = {
      source: 'preorder-purchase',
      createdAt: new Date().toISOString(),
      productCode: item.code || item.sku || item.skuId || preorderSkuKey(item) || '',
      productName: item.title || item.name || '',
      costTwd: Number(item.cost || item.costTwd || 0),
      platform: platform,
      trackingNo: inquiry.supplierTrackingNo || '',
      progress: inquiry.purchaseStatusLabel || inquiry.purchaseStatus || '待下單',
      date: formatInputDate(new Date()),
      note: '預購單 ' + (inquiry.id || '-') + (inquiry.purchaseNote ? ' / ' + inquiry.purchaseNote : '')
    };
    if (applyFreightProductDraft(draft)) return;
    sessionStorage.setItem('lingzanzan-v1-product-create-draft', JSON.stringify(draft));
    location.href = './admin-products.html?fromPreorder=1&v=20260712-preorder-platform-carry-1#product-create';
  }

  function openProductEditorModal(product) {
    var shell = document.querySelector('[data-product-editor-shell]');
    var title = document.querySelector('[data-product-editor-title]');
    if (!shell) return;
    shell.classList.add('is-modal');
    document.body.classList.add('product-editor-open');
    if (title) title.textContent = product ? '編輯商品：' + (product.code || product.title || product.id) : '新增商品';
  }

