  function applyProductCreateModeFromUrl(force) {
    if ((location.pathname.split('/').pop() || '') !== 'admin-products.html') return;
    var params = new URLSearchParams(location.search);
    if (params.get('mode') !== 'preorder' || (!force && state._preorderProductModeApplied)) return;
    var visibilityMode = document.querySelector('[data-product-visibility-mode]');
    if (visibilityMode) visibilityMode.value = 'preorder';
    state._preorderProductModeApplied = true;
  }
