        if (!inlineProduct || !inlineRow) return;
        var inlinePrice = Number(inlineRow.querySelector('[data-product-inline-sale]')?.value || 0);
        var inlineCost = Number(inlineRow.querySelector('[data-product-inline-cost]')?.value || 0);
        var inlineStorefrontEligible = productStorefrontEligible(inlineProduct);
        var inlineRequestedVisible = inlineStorefrontEligible
          ? inlineRow.querySelector('[data-product-inline-visible]')?.checked !== false
          : productStorefrontRequested(inlineProduct);
