        if (!window.confirm('確定刪除勾選的 ' + ids.length + ' 個商品嗎？')) return;
        state.deletedProductIds = Array.from(new Set((state.deletedProductIds || []).concat(ids)));
        state.products = state.products.filter(function (product) { return ids.indexOf(product.id) === -1; });
        state.skus = state.skus.filter(function (sku) { return ids.indexOf(sku.productId) === -1; });
        saveLocal();
