    document.addEventListener('change', function (event) {
      var target = event.target;
      if (!target || !target.matches) return;
      if (target.matches('[data-stocktake-warehouse]')) {
        stocktakeDraft.warehouse = target.value || stocktakeDraft.warehouse;
        localStorage.setItem(STOCKTAKE_WAREHOUSE_KEY, stocktakeDraft.warehouse);
        stocktakeDraft.compareStarted = true;
        saveStocktakeDraft();
        renderStocktakePanel();
      }
      if (target.matches('[data-stocktake-pending-warehouse]')) {
        stocktakeDraft.warehouse = target.value || stocktakeDraft.warehouse;
        localStorage.setItem(STOCKTAKE_WAREHOUSE_KEY, stocktakeDraft.warehouse);
        saveStocktakeDraft();
      }
      if (target.matches('[data-stocktake-pending-upload]')) {
        var pendingId = target.getAttribute('data-stocktake-pending-upload');
        var card = target.closest('[data-pending-stock-review-card]');
        if (!pendingId || !card || !target.files || !target.files.length) return;
        setPendingStockReviewStatus(card, '正在讀取圖片…', '');
        filesToDataUrls(target.files).then(function (images) {
          if (!images.length) throw new Error('沒有可用圖片');
          images.forEach(function (dataUrl) { stagePendingStockReviewImage(card, dataUrl, '上傳圖片'); });
          target.value = '';
        }).catch(function (error) {
          setPendingStockReviewStatus(card, '圖片讀取失敗：' + (error && error.message ? error.message : '請重新選擇'), 'error');
        });
      }
    });

    document.addEventListener('paste', function (event) {
      var target = event.target;
      if (!target || !target.closest) return;
      var productImageCard = target.closest('.product-image-card');
      var pendingBox = target.closest('[data-stocktake-pending-card]');
      var pendingReviewBox = target.closest('[data-pending-stock-review-card]');
      var quickReviewBox = target.closest('[data-quick-stock-review-card]');
      if (!productImageCard && !pendingBox && !pendingReviewBox && !quickReviewBox) return;
      var hasImage = Array.from((event.clipboardData && event.clipboardData.files) || []).some(function (file) {
        return String(file.type || '').match(/^image\//);
      });
      if (!hasImage) return;
      event.preventDefault();
      clipboardFilesToDataUrls(event).then(function (images) {
        if (!images.length) return;
        if (pendingBox) {
          openScissorTool(images[0], 'stocktake-pending', pendingBox);
          return;
        }
        if (pendingReviewBox) {
          openScissorTool(images[0], 'pending-stock-review', pendingReviewBox);
          return;
        }
        if (quickReviewBox) {
          openScissorTool(images[0], 'quick-stock-review', quickReviewBox);
          return;
        }
        openScissorTool(images[0], 'product');
      });
    });

